independent_check_command:
$summary=Get-Content -LiteralPath reports\gate10a\machine_summary.json -Raw | ConvertFrom-Json
$protocol=Get-Content -LiteralPath reports\gate10a\protocol.json -Raw | ConvertFrom-Json
$failures=@()
$material=@()
$lookup=@{}
foreach($row in $summary.architectures){$lookup[$row.design+'/'+$row.architecture]=$row}
foreach($row in $summary.comparisons){
  $c=$lookup[$row.design+'/'+$row.candidate]; $r=$lookup[$row.design+'/'+$row.reference]
  foreach($spec in @(@('worst_drop_v','worst'),@('p99_drop_v','p99'))){
    $observed=[double]$c.ir.($spec[0])-[double]$r.ir.($spec[0]); $relative=$observed/[double]$r.ir.($spec[0])
    if([Math]::Abs($observed-[double]$row.('delta_'+$spec[1]+'_ir_v')) -gt 1e-15 -or [Math]::Abs($relative-[double]$row.('delta_'+$spec[1]+'_ir_fraction')) -gt 1e-12){$failures += 'voltage_delta:'+ $row.design+'/'+$row.candidate}
  }
  $voltage=($row.delta_worst_ir_v -le -$protocol.material_absolute_drop_reduction_v -and $row.delta_worst_ir_fraction -le -$protocol.material_relative_reduction -and $row.delta_p99_ir_v -le -$protocol.material_absolute_drop_reduction_v -and $row.delta_p99_ir_fraction -le -$protocol.material_relative_reduction)
  $dynamic=($row.delta_dynamic_power_fraction -le $protocol.maximum_dynamic_or_peak_segment_current_regression)
  $current=($row.delta_peak_segment_current_fraction -le $protocol.maximum_dynamic_or_peak_segment_current_regression)
  $benefit=$voltage -and $dynamic -and $current
  $adverse=($row.delta_worst_ir_v -ge $protocol.material_absolute_drop_reduction_v -and $row.delta_worst_ir_fraction -ge $protocol.material_relative_reduction -and $row.delta_p99_ir_v -ge $protocol.material_absolute_drop_reduction_v -and $row.delta_p99_ir_fraction -ge $protocol.material_relative_reduction)
  $cost=($row.delta_routed_scan_wire_fraction -le $protocol.modest_scan_wire_increase)
  if($benefit -ne $row.materiality.material_pi_benefit -or $adverse -ne $row.materiality.material_adverse_drop -or $cost -ne $row.materiality.modest_scan_wire_cost){$failures += 'threshold_assessment:'+ $row.design+'/'+$row.candidate}
  $material += [PSCustomObject]@{design=$row.design;candidate=$row.candidate;comparison_role=$row.comparison_role;voltage_benefit=$voltage;material_pi_benefit=$benefit;material_adverse_drop=$adverse;modest_cost=$cost;worst_drop_change_v=$row.delta_worst_ir_v;p99_drop_change_v=$row.delta_p99_ir_v}
}
function Get-Ranks([double[]]$values){
  $ranks=[double[]]::new($values.Count)
  $order=@(0..($values.Count-1) | Sort-Object { $values[$_] })
  $first=0
  while($first -lt $order.Count){$last=$first+1;while($last -lt $order.Count -and $values[$order[$last]] -eq $values[$order[$first]]){$last++};$rank=($first+1+$last)/2.0;for($i=$first;$i -lt $last;$i++){$ranks[$order[$i]]=$rank};$first=$last}
  return ,$ranks
}
function Get-Pearson([double[]]$left,[double[]]$right){
  $mx=($left | Measure-Object -Average).Average; $my=($right | Measure-Object -Average).Average
  $cov=0.0; $xx=0.0; $yy=0.0
  for($i=0;$i -lt $left.Count;$i++){ $dx=$left[$i]-$mx; $dy=$right[$i]-$my; $cov+=$dx*$dy; $xx+=$dx*$dx; $yy+=$dy*$dy }
  return $cov/[Math]::Sqrt($xx*$yy)
}
$spatial=@()
foreach($design in @('b14_opt','b15_opt')){
  $reference=if($design -eq 'b14_opt'){'B3T'}else{'B2'}
  foreach($method in @($reference,'CS_C1')){
    $row=$lookup[$design+'/'+$method]; $path=$row.spatial_vectors.path.Substring(7)
    $vectors=Get-Content -LiteralPath $path -Raw | ConvertFrom-Json
    foreach($resolution in @(4,8)){
      $grid=$vectors.grids.([string]$resolution); $domain=@($grid.domain.bin_ids)
      $x=[double[]]@($domain | ForEach-Object { $grid.activity.values[$_] })
      $y=[double[]]@($domain | ForEach-Object { $grid.static_vdd_drop.values[$_] })
      $rho=Get-Pearson (Get-Ranks $x) (Get-Ranks $y); $pearson=Get-Pearson $x $y
      $reported=$grid.activity_vs_static_ir.primary
      if([Math]::Abs($rho-$reported.spearman_rho) -gt 1e-12 -or [Math]::Abs($pearson-$reported.pearson_r) -gt 1e-12){$failures += 'spatial_statistic:'+ $design+'/'+$method+'/'+$resolution}
      $spatial += [PSCustomObject]@{design=$design;method=$method;resolution=$resolution;occupied_bins=$domain.Count;pearson_r=$pearson;spearman_rho=$rho;criterion_pass=($rho -ge $protocol.spatial_proxy_min_spearman)}
    }
  }
}
$correspondence=(@($spatial | Where-Object criterion_pass -eq $false).Count -eq 0)
$pact=@($material | Where-Object comparison_role -ne 'control')
$primaries=@($pact | Where-Object comparison_role -eq 'primary')
if(@($primaries | Where-Object { -not ($_.material_pi_benefit -and $_.modest_cost) }).Count -eq 0){$expected='PACT_GATE10A_PHYSICAL_IMPACT_SUPPORTED';$recommendation='CONTINUE'}
elseif(@($pact | Where-Object material_pi_benefit -eq $true).Count -gt 0){$expected='PACT_GATE10A_PARTIAL_PHYSICAL_IMPACT';$recommendation=if(@($primaries | Where-Object { $_.material_pi_benefit -and $_.modest_cost }).Count -gt 0 -and @($primaries | Where-Object material_adverse_drop -eq $true).Count -eq 0){'CONTINUE'}else{'PIVOT'}}
elseif($correspondence){$expected='PACT_GATE10A_PROXY_CORRELATION_ONLY';$recommendation='PIVOT'}
else{$expected='PACT_GATE10A_NO_MATERIAL_PHYSICAL_IMPACT';$recommendation='FREEZE'}
if($expected -ne $summary.decision.classification -or $recommendation -ne $summary.decision.recommendation){$failures += 'campaign_decision'}
if($summary.qualification_errors.Count -ne 0 -or @($summary.architectures | Where-Object status -ne 'QUALIFIED').Count -gt 0){$failures += 'incomplete_final_evidence'}
foreach($design in @('b14_opt','b15_opt')){ $rows=@($summary.architectures | Where-Object design -eq $design);if(@($rows.pdn_geometry_sha256 | Select-Object -Unique).Count -ne 1 -or @($rows.sources_sha256 | Select-Object -Unique).Count -ne 1){$failures += 'common_physical_basis:'+ $design} }
[PSCustomObject]@{status=if($failures.Count -eq 0){'PASS'}else{'FAIL'};failures=$failures;qualified_architectures=$summary.architectures.Count;comparison_checks=$material;primary_spatial_checks=$spatial;spatial_correspondence=$correspondence;classification=$expected;recommendation=$recommendation} | ConvertTo-Json -Depth 7
